export type Subscription = {
  /** Streams incremental text tokens from a running Sidekick agent session. Subscribe with the agentSessionId returned when starting a session; each event carries a text chunk that should be appended to the in-progress assistant message. The stream ends when the session status transitions to IDLE or an error occurs. */
  agentSessionDelta: AgentSessionDelta;
  /**
   * Subscribes to customer card instance changes for a given customer.
   *
   * Emits a `CustomerCardInstanceChange` whenever a card transitions from loading to loaded or errored, or when a card is reloaded. The first message is a `SubscriptionAcknowledgement`. Requires the `customer:read` permission; the `customerCardConfig.apiUrl` and `customerCardConfig.apiHeaders` fields within the payload additionally require `customerCardConfigApiDetails:read`.
   */
  customerCardInstanceChanges: CustomerCardInstanceChangesResult;
  /** Subscribe to real-time create, update, and delete events for all customers in the workspace. Each event includes a `changeType` and the affected `Customer`. */
  customerChanges: CustomerChange;
  /**
   * Subscribe to real-time changes for a specific discussion. Fires when the discussion is created,
   * updated, resolved, deleted, or when a message is added or updated. The changeType field indicates
   * whether the change is an addition, update, or removal. When a message event fires, discussionMessage
   * is populated with the affected message; otherwise it is null. Requires thread:read permission.
   */
  discussionChanges: DiscussionChange;
  /**
   * Real-time subscription that fires whenever an internal notification is created or updated for the currently authenticated user.
   * Each event carries a `changeType` of `ADDED` (new notification) or `UPDATED` (e.g. read/archived state changed) together with the full notification object.
   * Requires the `user:read` permission.
   */
  internalNotificationChanges: InternalNotificationChange;
  /** Fires for the current user whenever one of their Sidekick sessions receives a new agent response and becomes unread (i.e. the session settles into IDLE). Use the returned discussionId to refetch or highlight the relevant session. The session becomes read again when it is opened or explicitly marked read. */
  sidekickSessionsChanged: SidekickSessionsChange;
  /** Real-time subscription that fires whenever a thread is created or updated. Accepts optional filters to limit events by thread status or the time the status last changed. Each event includes the full current thread and a `changeType` indicating whether the thread was created or updated. */
  threadChanges: ThreadChange;
  /** Workspace-scoped subscription that fires whenever a thread field schema is created, updated, or deleted. Use `changeType` on the result to distinguish the operation. Requires the `threadFieldSchema:read` permission. */
  threadFieldSchemaChanges: ThreadFieldSchemaChange;
  /** Subscribes to all timeline entry changes (added, updated, or removed) for a specific thread. Requires the `timeline:read` permission. */
  threadTimelineChanges: TimelineEntryChange;
  /** Subscribes to all timeline entry changes (added, updated, or removed) across every thread for a given customer. Requires the `timeline:read` permission. */
  timelineChanges: TimelineEntryChange;
  /** Workspace-scoped subscription that fires whenever a member's status changes. Delivers a `UserChange` payload with the updated `User` and a `changeType` of `UPDATED`. Requires the `user:read` permission. */
  userChanges: UserChange;
};


