export type ThreadDiscussion = {
  /** Channel-specific details for the discussion (Slack channel info, email recipients, or agent session ID). The concrete type depends on the discussion type. */
  channelDetails?: Maybe<ThreadDiscussionChannelDetails>;
  createdAt: DateTime;
  createdBy: Actor;
  /** @deprecated Use channelDetails.emailRecipients instead */
  emailRecipients: Array<Scalars['String']['output']>;
  id: Scalars['ID']['output'];
  /**
   * True when the discussion has an unread agent response (set when a Sidekick agent
   * session settles into IDLE, cleared when the session is opened / marked read).
   */
  isUnread: Scalars['Boolean']['output'];
  /** Timestamp of the most recent message in the discussion. Null when no messages have been posted yet. */
  lastActivityAt?: Maybe<DateTime>;
  messages: ThreadDiscussionMessageConnection;
  /**
   * User-authored messages that the user has submitted but the agent has not
   * picked up yet because it was mid-turn. Empty for non-AGENT_SESSION
   * discussions. Frontend can render these as greyed-out preview bubbles
   * pinned to the bottom of the chat; they disappear when the agent picks
   * them up (a real ThreadDiscussionMessage is created at that point with a
   * correctly-ordered timestamp) or when the queue is cleared by error /
   * timeout / manual stop.
   */
  queuedAgentSessionMessages: Array<QueuedAgentSessionMessage>;
  resolvedAt?: Maybe<DateTime>;
  /** @deprecated Use channelDetails.slackChannelId instead */
  slackChannelId?: Maybe<Scalars['String']['output']>;
  /** @deprecated Use channelDetails.slackChannelName instead */
  slackChannelName?: Maybe<Scalars['String']['output']>;
  /** @deprecated Use channelDetails.slackMessageLink instead */
  slackMessageLink?: Maybe<Scalars['String']['output']>;
  /** @deprecated Use channelDetails.slackTeamId instead */
  slackTeamId?: Maybe<Scalars['String']['output']>;
  /** When the discussion was started from an entity page (company, tenant, etc.). Null when source is thread-only, a plain link, or absent. */
  sourceEntityId?: Maybe<Scalars['ID']['output']>;
  /** The type of entity for sourceEntityId (e.g. COMPANY, TENANT). Null when sourceEntityId is not set. */
  sourceEntityType?: Maybe<DiscussionSourceEntityType>;
  /**
   * The page path where this discussion was started (e.g. '/workspace/ws_xxx/insights').
   * Null when not set (older rows, or thread/entity-only context).
   */
  sourcePageLink?: Maybe<Scalars['String']['output']>;
  /**
   * High-level status of the discussion. RESOLVED when resolvedAt is set.
   * For agent session discussions, IN_PROGRESS while the agent is running;
   * APPROVAL_REQUESTED when the agent has finished working but is blocked on an
   * unresolved approval request; otherwise IDLE.
   * Non-agent-session discussions are IDLE until resolved.
   */
  status: ThreadDiscussionStatus;
  /** The support thread when threadId is set. Null when the discussion has no thread (e.g. some global Sidekick sessions). */
  thread?: Maybe<Thread>;
  /** The ID of the Plain thread this discussion is attached to. Null for global Sidekick agent sessions that were not started from a thread. */
  threadId?: Maybe<Scalars['ID']['output']>;
  title: Scalars['String']['output'];
  /** @deprecated Use channelDetails instead */
  type: ThreadDiscussionType;
  updatedAt: DateTime;
  updatedBy: Actor;
  /** Who can see this discussion. WORKSPACE means visible to all workspace members, USER means visible only to the creator. Null when not yet set. */
  visibility?: Maybe<ThreadDiscussionVisibility>;
};


