/** Defines the shape and behaviour of a custom field that can be attached to threads. */
export type ThreadFieldSchema = {
  createdAt: DateTime;
  createdBy: InternalActor;
  defaultBooleanValue?: Maybe<Scalars['Boolean']['output']>;
  defaultDateValue?: Maybe<DateTime>;
  defaultNumberValue?: Maybe<Scalars['Float']['output']>;
  defaultStringValue?: Maybe<Scalars['String']['output']>;
  /** If non-empty, this field is only shown when the thread has at least one of the listed label types. */
  dependsOnLabels: Array<DependsOnLabelType>;
  /** If set, this field is only shown when the referenced sibling field has a specific value. */
  dependsOnThreadField?: Maybe<DependsOnThreadFieldType>;
  description: Scalars['String']['output'];
  /** Valid options for ENUM-typed fields. Empty for all other field types. */
  enumValues: Array<Scalars['String']['output']>;
  id: Scalars['ID']['output'];
  /** When true, Plain's AI will attempt to automatically fill this field based on the thread's content. Only supported for ENUM and BOOL field types. */
  isAiAutoFillEnabled: Scalars['Boolean']['output'];
  /** When true, the field value can only be set via the API and is not editable by agents in the Plain UI. */
  isClientReadonly: Scalars['Boolean']['output'];
  /** When true, a thread cannot be marked as done until this field has a value. */
  isRequired: Scalars['Boolean']['output'];
  /** A stable, URL-safe identifier for the field used when reading and writing values. Set at creation and immutable thereafter. */
  key: Scalars['String']['output'];
  label: Scalars['String']['output'];
  /** Controls the position of this field relative to other thread field schemas in the UI. */
  order: Scalars['Int']['output'];
  type: ThreadFieldSchemaType;
  updatedAt: DateTime;
  updatedBy: InternalActor;
};

export type ThreadFieldSchemaChange = {
  changeType: ChangeType;
  threadFieldSchema: ThreadFieldSchema;
};

export type ThreadFieldSchemaConnection = {
  edges: Array<ThreadFieldSchemaEdge>;
  pageInfo: PageInfo;
};

export type ThreadFieldSchemaEdge = {
  cursor: Scalars['String']['output'];
  node: ThreadFieldSchema;
};

export type ThreadFieldSchemaOrderInput = {
  order: Scalars['Int']['input'];
  threadFieldSchemaId: Scalars['ID']['input'];
};

/** The data type of a thread field schema, which determines which value field is used when reading or writing thread field values. */
export type ThreadFieldSchemaType =
  /** Stores a boolean value. */
  | 'BOOL'
  /** Stores a monetary amount as a float. */
  | 'CURRENCY'
  /** Stores a date/time value as a DateTime scalar. */
  | 'DATE'
  /** Stores one value chosen from a predefined set of allowed string values. */
  | 'ENUM'
  /** Stores a numeric value as a float. */
  | 'NUMBER'
  /** Stores a free-text value as a string. */
  | 'STRING';

/** One cell of a thread heatmap grid, representing activity for a specific day-of-week and hour-of-day combination. */
export type ThreadHeatmapHour = {
  /** This cell's share of total volume across the entire grid, expressed as a value 0–100. */
  percentage: Scalars['Float']['output'];
  /** Number of threads active in this hour/day bucket. */
  total: Scalars['Int']['output'];
};

/** Result of a `threadHeatmapMetric` query. Activity distributed across a 7 × 24 grid (Monday–Sunday, hour 0–23 UTC). */
export type ThreadHeatmapMetric = {
  /** 7 elements (Monday=0 … Sunday=6), each containing 24 hourly buckets (hour 0–23 UTC). */
  days: Array<Array<ThreadHeatmapHour>>;
};

export type ThreadHeatmapMetricInput = {
  filters?: InputMaybe<ThreadMetricFilters>;
  /** ISO 8601 format (e.g. 2024-10-28T18:30:00Z). */
  from: Scalars['String']['input'];
  metricName: HeatmapMetricName;
  /** ISO 8601 format (e.g. 2024-10-28T18:30:00Z). */
  to: Scalars['String']['input'];
};

