export type ThreadSingleValueMetricInput = {
  filters?: InputMaybe<ThreadMetricFilters>;
  /** ISO 8601 format (e.g. 2024-10-28T18:30:00Z). Required for all metrics except all-time counts (e.g. threads_all_time_count_done), which reject a date range. */
  from?: InputMaybe<Scalars['String']['input']>;
  groupBy?: InputMaybe<Array<ThreadMetricGroupByInput>>;
  metricName: SingleValueMetricName;
  /** ISO 8601 format (e.g. 2024-10-28T18:30:00Z). Required for all metrics except all-time counts (e.g. threads_all_time_count_done), which reject a date range. */
  to?: InputMaybe<Scalars['String']['input']>;
};

export type ThreadSingleValueMetricValue = {
  /** The group this value belongs to. Null when no `groupBy` was requested. */
  group?: Maybe<ThreadMetricGroup>;
  /** The computed metric value for this group bucket. Null when no data exists in the requested period. */
  value?: Maybe<Scalars['Float']['output']>;
};

/** The lifecycle status of a thread. */
export type ThreadStatus =
  /** The support team has finished with the thread for now. It reverts to TODO automatically when new activity arrives. */
  | 'DONE'
  /** The thread is temporarily paused until a timer expires or the customer replies. */
  | 'SNOOZED'
  /** The thread requires attention from the support team. */
  | 'TODO';

export type ThreadStatusDetail = ThreadStatusDetailCreated | ThreadStatusDetailDoneAutomaticallySet | ThreadStatusDetailDoneManuallySet | ThreadStatusDetailIgnored | ThreadStatusDetailInProgress | ThreadStatusDetailLinearUpdated | ThreadStatusDetailNewReply | ThreadStatusDetailReplied | ThreadStatusDetailSnoozed | ThreadStatusDetailThreadDiscussionResolved | ThreadStatusDetailThreadLinkUpdated | ThreadStatusDetailUnsnoozed | ThreadStatusDetailWaitingForCustomer | ThreadStatusDetailWaitingForDuration | ThreadStatusDetailWaitingIndefinitely;

